/**
 * Freelance OS Dashboard Bundle for Thymer
 * Auto-generated by build.mjs
 */

const STYLES = "/* Freelance OS Dashboard for Thymer */
.os-app, .os-modal-backdrop {
  --os-text: var(--text-normal, #e0e0e0);
  --os-muted: color-mix(in srgb, var(--text-muted, #8b949e) 75%, var(--text-normal, #e0e0e0));
  --os-border: var(--ed-container-border-color, #30363d);
  --os-surface: var(--cards-bg, #161b22);
  --os-surface-hover: var(--cards-hover-bg, #21262d);
  --os-accent: var(--ed-link-color, #58a6ff);
  --os-gap: 16px;
}
.os-app {
  width: 100% !important;
  max-width: 100% !important;
  height: 100%;
  overflow-y: auto;
  overflow-x: hidden !important;
  box-sizing: border-box;
  color: var(--os-text);
  font: 14px/1.4 -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-variant-numeric: tabular-nums;
  position: relative;
  container-type: inline-size;
  container-name: osApp;
}
.os-shell { padding: 20px 24px; --os-gap: 16px; min-width: 0; min-height: 100%; }
.os-shell:focus { outline: none; }
.os-workflow-modes, .os-action-tabs, .os-review-steps { display: flex; gap: 6px; flex-wrap: wrap; }
.os-workflow-modes { margin-bottom: 20px; padding-bottom: 12px; border-bottom: 1px solid var(--os-border); }
.os-workflow { min-width: 0; }
.os-workflow h2 { font-size: 20px; font-weight: 650; }
.os-workflow h3 { font-size: 14px; margin: 24px 0 8px; }
.os-workflow-heading { display: flex; justify-content: space-between; gap: 16px; align-items: center; }
.os-focus-count { font-size: 16px; color: var(--os-muted); white-space: nowrap; flex-shrink: 0; }
.os-workflow p, .os-workflow select, .os-workflow summary, .os-workflow button { font-family: inherit; }
.os-focus-list { margin: 12px 0 24px; border-bottom: 1px solid var(--os-border); padding-bottom: 16px; }
.os-action-tabs { margin-bottom: 12px; }
.os-start-here { margin: 12px 0 20px; padding: 12px 16px; border: 1px solid var(--os-border); border-radius: 8px; background: var(--os-surface); }
.os-start-here-heading h3 { margin: 0; }
.os-start-here-heading .os-action-meta { margin: 3px 0 0; }
.os-start-here-incomplete { color: var(--os-warning, #d29922); font-weight: 550; }
.os-start-here-list { list-style: none; margin: 10px 0 0; padding: 0; }
.os-start-here-item { padding: 10px 0; border-top: 1px solid var(--os-border); }
.os-start-here-row { display: flex; justify-content: space-between; align-items: center; gap: 16px; }
.os-start-here-copy { min-width: 0; flex: 1; }
.os-start-here-title { display: block; max-width: 100%; padding: 0; border: 0; background: transparent; color: var(--os-text); font: inherit; font-weight: 600; text-align: left; cursor: pointer; overflow-wrap: anywhere; }
.os-start-here-title:hover { color: var(--os-accent); text-decoration: underline; text-underline-offset: 3px; }
.os-start-here-project { margin: 2px 0 0; color: var(--os-muted); font-size: 12px; overflow-wrap: anywhere; }
.os-start-here-reasons { display: flex; flex-wrap: wrap; gap: 2px 18px; margin: 4px 0 0; padding-left: 16px; color: var(--os-muted); font-size: 11px; line-height: 1.5; }
.os-start-here-add { flex: 0 0 auto; }
.os-start-here-add:disabled { cursor: not-allowed; }
.os-start-here-title:focus-visible, .os-start-here-add:focus-visible { outline: 2px solid var(--os-accent); outline-offset: 3px; }
.os-queue-presets { display: flex; gap: 6px; flex-wrap: wrap; margin: -2px 0 12px; }
.os-preset { padding: 5px 10px; border: 1px solid var(--os-border); border-radius: 999px; background: transparent; color: var(--os-muted); font: inherit; font-size: 12px; cursor: pointer; }
.os-preset:hover { color: var(--os-text); border-color: var(--os-accent); }
.os-preset.active { color: var(--os-text); background: var(--os-surface-hover); border-color: var(--os-accent); font-weight: 600; }
.os-preset:focus-visible, .os-tab:focus-visible, .os-queue-controls input:focus-visible, .os-queue-controls select:focus-visible { outline: 2px solid var(--os-accent); outline-offset: 2px; }
.os-queue-controls { display: flex; gap: 10px; margin: 12px 0; flex-wrap: wrap; }
.os-queue-controls input { flex: 1 1 200px; min-width: 0; width: auto; }
.os-queue-controls select { flex: 0 1 280px; min-width: 0; width: auto; max-width: 100%; }
.os-queue-summary { color: color-mix(in srgb, var(--os-muted) 75%, var(--os-text)); font-size: 12px; margin: 8px 0 4px !important; overflow-wrap: anywhere; }
.os-followup-due { color: #fb923c; }
.os-action-row { display: flex; align-items: flex-start; gap: 12px; padding: 14px 0; border-bottom: 1px solid var(--os-border); }
.os-action-done { flex: 0 0 auto; margin-top: 4px; accent-color: var(--os-accent); }
.os-action-copy { flex: 1; min-width: 0; }
.os-action-title { display: block; padding: 0; border: 0; background: none; color: var(--os-text); font: inherit; font-weight: 550; text-align: left; cursor: pointer; overflow-wrap: anywhere; }
.os-action-title:hover { color: var(--os-accent); text-decoration: underline; }
.os-action-meta { color: color-mix(in srgb, var(--os-muted) 75%, var(--os-text)); font-size: 12px; line-height: 1.5; margin-top: 4px; overflow-wrap: anywhere; }
.os-action-buttons { display: flex; gap: 6px; align-items: flex-start; }
.os-action-row:has(.os-action-edit[open]) { flex-wrap: wrap; }
.os-action-row:has(.os-action-edit[open]) .os-action-buttons { flex: 1 1 100%; margin-left: 26px; flex-wrap: wrap; min-width: 0; }
.os-action-edit[open] { flex: 1 1 100%; min-width: 0; }
.os-workflow summary { cursor: pointer; font-size: 12px; padding: 8px 0; color: var(--os-muted); }
.os-action-edit { min-width: 40px; }
.os-action-editor { display: grid; gap: 8px; width: 100%; max-width: 460px; margin-top: 8px; }
.os-action-edit:not([open]) .os-action-editor { display: none; }
.os-action-editor label, .os-action-editor input { min-width: 0; }
.os-action-editor label, .os-review-form label, .os-settings-fields label { display: grid; gap: 6px; font-size: 12px; color: var(--os-muted); }
.os-wait-note { font-size: 12px; color: color-mix(in srgb, var(--os-muted) 75%, var(--os-text)); margin-top: 6px; overflow-wrap: anywhere; }
.os-workflow-empty { color: color-mix(in srgb, var(--os-muted) 75%, var(--os-text)); padding: 16px 0; font-size: 13px; }
.os-workflow-message { padding: 12px; background: var(--os-surface); border: 1px solid var(--os-border); border-radius: 6px; margin-bottom: 14px !important; }
.os-project-attention { display: flex; gap: 20px; justify-content: space-between; border-bottom: 1px solid var(--os-border); padding: 14px 0; }
.os-project-checkin-copy { flex: 1 1 240px; min-width: 0; }
.os-project-recovery { color: var(--os-warning, #d29922) !important; }
.os-project-cues { margin-top: 6px; color: var(--os-muted); font-size: 12px; }
.os-project-cues summary { cursor: pointer; padding: 2px 0; }
.os-project-cue-list { display: grid; gap: 3px; margin-top: 5px; }
.os-project-cue { min-width: 0; padding: 2px 0; border: 0; background: transparent; color: var(--os-accent); text-align: left; font: inherit; font-size: 12px; overflow-wrap: anywhere; cursor: pointer; }
.os-project-cue:hover { text-decoration: underline; }
.os-next-picker { display: flex; align-items: flex-start; gap: 6px; }
.os-next-picker select { max-width: 340px; min-width: 0; padding: 7px; background: var(--os-surface); color: var(--os-text); border: 1px solid var(--os-border); border-radius: 6px; }
.os-review-steps { margin-top: 16px; }
.os-review-discovery { display: grid; gap: 8px; margin-top: 20px; max-width: 800px; padding: 12px 14px; border: 1px solid var(--os-border); border-radius: 8px; background: var(--os-surface); }
.os-review-discovery p { margin: 0; }
.os-review-discovery-warning { color: var(--os-warning, #d29922) !important; }
.os-review-discovery > .os-button, .os-previous-priorities > .os-button { justify-self: start; }
.os-review-discovery-list { display: grid; gap: 6px; }
.os-review-discovery-candidate { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.os-review-discovery-candidate > span { flex: 1 1 180px; min-width: 0; overflow-wrap: anywhere; }
.os-previous-priorities { display: grid; gap: 8px; margin-top: 16px; max-width: 800px; padding: 14px; border: 1px solid var(--os-border); border-radius: 8px; background: var(--os-surface); }
.os-previous-heading { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; flex-wrap: wrap; }
.os-previous-heading h3 { margin: 0; }
.os-previous-heading p { margin: 0; }
.os-previous-priority-list { display: grid; gap: 2px; }
.os-previous-priority { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; padding: 8px 0; border-top: 1px solid var(--os-border); }
.os-previous-priority:first-child { border-top: 0; }
.os-previous-priority-copy { display: grid; gap: 2px; flex: 1 1 240px; min-width: 0; }
.os-previous-priority-title { overflow-wrap: anywhere; }
.os-review-form { display: grid; gap: 18px; margin-top: 24px; max-width: 800px; }
.os-review-form textarea { width: 100%; resize: vertical; min-height: 90px; background: var(--os-surface); border: 1px solid var(--os-border); color: var(--os-text); border-radius: 6px; padding: 10px 12px; font: inherit; }
.os-review-priority-bridge { display: grid; gap: 8px; padding: 14px; border: 1px solid var(--os-border); border-radius: 8px; background: color-mix(in srgb, var(--os-surface) 72%, transparent); }
.os-review-priority-bridge h3 { margin: 0; }
.os-review-priority-bridge > p { margin: 0; }
.os-review-priority-list { display: grid; gap: 8px; }
.os-review-priority-row { display: flex; align-items: center; gap: 8px; min-width: 0; padding-top: 8px; border-top: 1px solid var(--os-border); }
.os-review-priority-copy { flex: 1 1 220px; min-width: 0; overflow-wrap: anywhere; color: var(--os-text); }
.os-review-priority-controls { flex: 1 1 520px; min-width: 0; display: grid; grid-template-columns: minmax(120px, 1fr) minmax(150px, 1.3fr) auto auto; gap: 6px; }
.os-review-priority-controls select { min-width: 0; width: 100%; }
.os-review-priority-project { min-width: 0; width: auto; }
.os-review-priority-linked { color: var(--os-muted); font-size: 12px; }
.os-review-preview { white-space: pre-wrap; overflow-wrap: anywhere; font: inherit; font-size: 12px; color: var(--os-muted); max-height: 350px; overflow-y: auto; }
.os-review-save-row, .os-review-footer { display: flex; align-items: center; flex-wrap: wrap; gap: 12px; }
.os-review-footer { margin-top: 24px; justify-content: space-between; }
.os-review-done { padding: 8px 0 !important; color: var(--os-muted); font-size: 13px; }
.os-workflow-settings > p { max-width: 75ch; font-size: 13px; margin-top: 12px; }
.os-settings-fields { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; margin: 24px 0; max-width: 700px; }
@container osApp (max-width: 720px) {
  .os-project-attention { flex-direction: column; gap: 6px; padding: 10px 0; }
  .os-project-checkin-copy { flex: 0 1 auto; }
  .os-next-picker { display: grid; grid-template-columns: minmax(0, 1fr) auto auto; align-items: center; gap: 6px; }
  .os-next-picker select { flex: none; grid-column: 1; width: 100%; max-width: 100%; }
  .os-next-picker .os-button { white-space: nowrap; padding: 5px 7px; }
  .os-action-row { flex-wrap: wrap; }
  .os-action-buttons { margin-left: 25px; }
  .os-settings-fields { grid-template-columns: 1fr; }
  .os-review-priority-row { flex-wrap: wrap; }
  .os-review-priority-copy { flex-basis: 100%; }
  .os-review-priority-controls { flex-basis: 100%; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); }
  .os-review-priority-controls .os-review-priority-link, .os-review-priority-controls .os-review-priority-add { justify-self: start; }
  .os-review-priority-linked { flex: 1 1 100%; }
}
.os-capture-options { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; margin-top: 6px; font-size: 12px; color: color-mix(in srgb, var(--os-muted) 75%, var(--os-text)); }
.os-capture-context { color: var(--os-text); font-size: 12px; }
.os-capture-context:empty { display: none; }
.os-capture-project { min-width: 0; max-width: 200px; flex: 1 1 120px; background: var(--os-surface); color: var(--os-text); border: 1px solid var(--os-border); border-radius: 4px; padding: 3px 6px; font: inherit; }
.os-capture-priority { display: inline-flex; align-items: center; gap: 4px; white-space: nowrap; }
.os-capture-priority input { accent-color: var(--os-accent); }
.os-capture-feedback { font-size: 12px; color: var(--os-text); }
.os-capture-feedback:not(:empty) { margin-top: 6px; }
.os-invoice-card .os-badge { cursor: default; }
.os-metric:focus-visible { outline: 2px solid var(--os-accent); outline-offset: 3px; }
.os-app button:disabled { opacity: .55; cursor: wait; }
.os-client-value { display: grid; gap: 5px; margin: 6px 0; font-size: 11px; }
.os-client-value > div { display: flex; justify-content: space-between; gap: 10px; flex-wrap: wrap; }
.os-client-value dt { color: var(--os-muted); }
.os-client-value dd { margin: 0; color: var(--os-text); }
.os-client-contact { display: grid; gap: 3px; margin: 4px 0; font-size: 12px; overflow-wrap: anywhere; }
.os-client-contact-name { font-weight: 550; }
.os-client-contact a { color: var(--os-accent); text-decoration: underline; text-underline-offset: 3px; }
.os-client-contact-empty { color: var(--os-muted); }
.os-client-status { width: auto; max-width: 100%; min-width: 0; height: 26px; padding: 2px 7px; border: 1px solid transparent; border-radius: 5px; background: var(--os-surface-hover); color: var(--os-muted); font: inherit; font-size: 11px; cursor: pointer; }
.os-client-status:hover { border-color: var(--os-border); color: var(--os-text); }
.os-client-status:focus-visible { outline: 2px solid var(--os-accent); outline-offset: 2px; }
.os-client-plan-label { color: var(--os-muted); font-size: 11px; }
.os-billing { min-width: 0; }
.os-billing [hidden], .os-billing-dialog [hidden] { display: none; }
.os-billing-heading, .os-billing-heading-actions, .os-billing-toolbar { display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap; }
.os-billing-heading h2 { font-size: 20px; font-weight: 650; }
.os-billing-heading p { color: var(--os-muted); margin-top: 4px; font-size: 12px; }
.os-billing-heading-actions { justify-content: flex-end; }
.os-billing-summary { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 16px; margin: 22px 0 8px; padding-bottom: 18px; border-bottom: 1px solid var(--os-border); }
.os-billing-summary dt { color: var(--os-muted); font-size: 12px; margin-bottom: 5px; }
.os-billing-summary dd { margin: 0; font-size: 24px; font-weight: 600; line-height: 1.2; }
.os-billing-summary dd span { color: var(--os-muted); font-size: 12px; font-weight: 400; }
.os-billing-currency-note { color: var(--os-muted); font-size: 11px; }
.os-billing-message { margin: 14px 0; color: var(--os-text); font-size: 12px; }
.os-billing-toolbar { margin: 24px 0 14px; }
.os-billing-search { min-width: 180px; width: min(300px, 100%); }
.os-billing-table-wrap { width: 100%; max-width: 100%; overflow-x: auto; scrollbar-color: var(--os-border) var(--os-surface); }
.os-billing-table-wrap:focus-visible { outline: 2px solid var(--os-accent); outline-offset: 3px; }
.os-billing-table { width: 100%; min-width: 900px; border-collapse: collapse; text-align: left; font-size: 12px; }
.os-billing-table th, .os-billing-table td { padding: 12px 14px; border-bottom: 1px solid var(--os-border); vertical-align: top; }
.os-billing-table th:first-child, .os-billing-table td:first-child { padding-left: 0; }
.os-billing-table th:last-child, .os-billing-table td:last-child { padding-right: 0; }
.os-billing-table thead th { color: var(--os-muted); font-weight: 550; padding-top: 10px; padding-bottom: 9px; }
.os-billing-table tbody th { font-weight: 500; max-width: 260px; min-width: 170px; overflow-wrap: anywhere; }
.os-billing-table tbody tr:hover { background: var(--os-surface); }
.os-billing-table .os-billing-number { white-space: nowrap; text-align: right; font-variant-numeric: tabular-nums; }
.os-billing-detail { display: block; margin-top: 3px; color: var(--os-muted); font-size: 11px; font-weight: 400; }
.os-billing-overdue { color: var(--os-warning, #d29922); white-space: nowrap; }
.os-billing-overdue .os-billing-detail { color: inherit; }
.os-billing-row-action { min-height: 28px; padding: 4px 9px; font-size: 11px; white-space: nowrap; }
.os-billing-caption { text-align: left; color: var(--os-muted); font-size: 11px; padding: 8px 0 10px; }
.os-billing-confirm-summary { display: grid; gap: 5px; }
.os-billing-confirm-summary strong { font-size: 16px; overflow-wrap: anywhere; }
.os-billing-confirm-summary span { color: var(--os-muted); font-size: 13px; }
.os-billing-dialog { container-type: inline-size; container-name: billingDialog; }
.os-billing-form-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; }
.os-billing-error { color: var(--text-error, #f85149); font-size: 12px; margin: 0; line-height: 1.5; }
@container billingDialog (max-width: 360px) { .os-billing-form-grid { grid-template-columns: minmax(0, 1fr); } }
@container osApp (max-width: 760px) { .os-billing-summary { grid-template-columns: repeat(2, minmax(0, 1fr)); } .os-billing-toolbar { align-items: stretch; } .os-billing-search { width: 100%; } }
.os-client-form { container-type: inline-size; container-name: clientForm; }
.os-client-form-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; }
.os-client-form [hidden] { display: none; }
.os-client-care-plan summary { color: var(--os-muted); font-size: 12px; cursor: pointer; }
.os-client-care-plan[open] summary { margin-bottom: 12px; }
.os-form-help { font-size: 12px; line-height: 1.5; color: var(--os-muted); margin: 0; }
.os-client-form-error { font-size: 12px; line-height: 1.5; color: var(--text-error, #f85149); margin: 0; }
@container clientForm (max-width: 360px) { .os-client-form-grid { grid-template-columns: minmax(0, 1fr); } }
.os-main, .os-agenda, .os-rail { min-width: 0; }
.os-card-bottom, .os-client-meta { flex-wrap: wrap; }
.os-project-next-link { display: block; width: 100%; min-width: 0; padding: 5px 0; border: 0; background: transparent; color: var(--os-accent); text-align: left; font: inherit; font-size: 12px; overflow-wrap: anywhere; cursor: pointer; }
.os-project-next-link:hover { text-decoration: underline; }
.os-project-next-label { font-weight: 650; }
.os-filter-search { flex-wrap: wrap; min-width: 0; }
.os-app input, .os-app select { font-family: inherit; }
.os-app input:focus-visible, .os-app select:focus-visible { outline: 2px solid var(--os-accent); outline-offset: 2px; }

/* Force inner content wrappers full width in Thymer (break out of 720px reader constraint)
   DO NOT touch .panel so Thymer's multi-panel grid sizing is never disrupted */
.panel-body:has(.os-app),
.panel-scroller-y:has(.os-app),
.panel-content:has(.os-app),
.empty-msg-panel:has(.os-app),
.layout-margin:has(.os-app),
.editor:has(.os-app) {
  max-width: 100% !important;
  width: 100% !important;
  padding-left: 0 !important;
  padding-right: 0 !important;
  margin-left: 0 !important;
  margin-right: 0 !important;
}

.os-app *, .os-app *::before, .os-app *::after { box-sizing: border-box; }
.os-app h1, .os-app h2, .os-app p { margin: 0; padding: 0; border: 0; }

/* Header */
.os-header { display: flex; justify-content: space-between; gap: 14px; align-items: center; margin-bottom: 20px; flex-wrap: wrap; }
.os-identity { display: flex; align-items: center; gap: 10px; flex-shrink: 0; }
.os-identity > .os-icon { width: 32px; height: 32px; color: var(--os-accent); display: flex; align-items: center; }
.os-identity > .os-icon svg { width: 28px; height: 28px; }
.os-app h1 { font-size: 22px; font-weight: 700; line-height: 1.2; letter-spacing: -.02em; color: var(--os-text); }
.os-app .os-subtitle { font-size: 12px; color: color-mix(in srgb, var(--os-muted) 75%, var(--os-text)); margin-top: 2px; }

.os-capture { position: relative; flex: 1 1 200px; max-width: 480px; }
.os-capture-field { display: flex; align-items: center; gap: 8px; min-height: 36px; padding: 0 10px; border: 1px solid var(--os-border); border-radius: 8px; background: var(--os-surface); transition: border-color .15s; }
.os-capture-field:focus-within { border-color: var(--os-accent); }
.os-capture-input { flex: 1 1 auto; min-width: 0; padding: 6px 0; border: 0; background: transparent; color: var(--os-text); font-family: inherit; font-size: 13px; }
.os-capture-input:focus { outline: none; }
.os-capture-btn { background: none; border: none; cursor: pointer; color: var(--os-muted); display: flex; align-items: center; padding: 4px 6px; font-size: 14px; border-radius: 4px; }
.os-capture-btn:hover { color: var(--os-text); background: var(--os-surface-hover); }

.os-button { display: inline-flex; align-items: center; justify-content: center; gap: 6px; padding: 7px 12px; min-height: 32px; border: 1px solid var(--os-border); border-radius: 6px; color: var(--os-text); background: var(--os-surface); cursor: pointer; font-size: 12px; font-weight: 500; transition: background .1s, border-color .1s; white-space: nowrap; }
.os-button:hover { background: var(--os-surface-hover); border-color: var(--os-accent); }
.os-button.os-primary { background: #38bdf8; border-color: #38bdf8; color: #0f172a; font-weight: 600; }
.os-button.os-primary:hover { background: #0ea5e9; }

/* Pulse KPI Bar */
.os-pulse { display: grid; grid-template-columns: repeat(auto-fit, minmax(130px, 1fr)); border-block: 1px solid var(--os-border); padding-block: 14px; margin-bottom: 22px; gap: 12px; }
.os-metric { padding-inline: 14px; border-left: 1px solid var(--os-border); min-width: 0; cursor: pointer; border-radius: 6px; transition: background .15s; overflow: hidden; }
.os-metric:first-child { padding-left: 0; border-left: 0; }
.os-metric:hover { background: var(--os-surface-hover); }
.os-metric-label { color: var(--os-muted); font-size: 11px; font-weight: 600; text-transform: uppercase; letter-spacing: .04em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.os-metric-value { display: flex; align-items: baseline; gap: 5px; font-size: 22px; font-weight: 700; line-height: 1.2; margin-top: 4px; }
.os-metric-unit { font-size: 12px; font-weight: 400; color: var(--os-muted); }
.os-metric-footnote { font-size: 12px; color: var(--os-muted); margin-top: 3px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

/* Main 3-Column Layout */
.os-cashflow { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 20px; padding: 0 0 18px; margin-bottom: 20px; border-bottom: 1px solid var(--os-border); }
.os-cash-heading { display: flex; justify-content: space-between; gap: 8px; align-items: baseline; }
.os-cash-heading h2 { font-size: 13px; font-weight: 600; }
.os-cash-heading span, .os-cash-note { font-size: 12px; color: var(--os-muted); }
.os-collection-rate progress { display: block; width: 100%; height: 6px; margin: 10px 0 6px; border: 0; border-radius: 3px; overflow: hidden; accent-color: var(--os-accent); }
.os-collection-rate progress::-webkit-progress-bar { background: var(--os-surface-hover); }
.os-collection-rate progress::-webkit-progress-value { background: var(--os-accent); }
.os-cash-action { display: flex; flex-direction: column; align-items: flex-start; gap: 3px; min-width: 0; padding: 4px 8px; border: 0; border-radius: 6px; text-align: left; font: inherit; background: transparent; color: var(--os-text); cursor: pointer; }
.os-cash-action:hover { background: var(--os-surface-hover); }
.os-cash-action > span, .os-invoice-timing { font-size: 12px; color: var(--os-muted); }
.os-cash-action strong { font-size: 16px; font-weight: 600; }
.os-cash-action small { font-size: 12px; color: var(--os-muted); overflow-wrap: anywhere; }
.os-cash-warning, .os-cash-warning > span { color: #fb923c; }
.os-support-time { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 20px; align-items: center; padding: 14px 16px; margin: -3px 0 20px; border: 1px solid var(--os-border); border-radius: 8px; background: var(--os-surface); }
.os-support-total { display: flex; align-items: baseline; gap: 7px; margin-top: 7px; font-size: 21px; font-weight: 700; font-variant-numeric: tabular-nums; }
.os-support-total small { font-size: 12px; font-weight: 500; color: var(--os-muted); }
.os-support-total > span { color: var(--os-muted); font-weight: 400; }
.os-support-time progress { display: block; width: 100%; height: 6px; margin: 8px 0 5px; border: 0; border-radius: 3px; overflow: hidden; accent-color: var(--os-accent); }
.os-support-time progress::-webkit-progress-bar { background: var(--os-surface-hover); }
.os-support-time progress::-webkit-progress-value { background: var(--os-accent); }
.os-support-actions { display: flex; flex-direction: column; align-items: stretch; gap: 7px; min-width: 160px; }
.os-support-actions .os-button { justify-content: center; }
.os-badge.status-unconfirmed { background: rgba(249, 115, 22, .15); color: #fb923c; }
.os-data-error { display: flex; gap: 12px; align-items: center; flex-wrap: wrap; padding: 12px 0; color: var(--os-text); }
.os-cashflow button:focus-visible, .os-app button:focus-visible, .os-app a:focus-visible { outline: 2px solid var(--os-accent); outline-offset: 3px; }
@container osApp (max-width: 1120px) { .os-cashflow { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; } }
@container osApp (max-width: 480px) { .os-cashflow { grid-template-columns: 1fr; gap: 8px; } }
@container osApp (max-width: 480px) { .os-start-here-row { align-items: flex-start; flex-direction: column; gap: 8px; } .os-start-here-reasons { gap: 2px 12px; } }
@container osApp (max-width: 580px) { .os-support-time { grid-template-columns: 1fr; gap: 12px; } .os-support-actions { flex-direction: row; flex-wrap: wrap; min-width: 0; } }

.os-grid { display: grid; grid-template-columns: 170px minmax(0, 1.3fr) minmax(280px, 1fr); gap: var(--os-gap); align-items: start; }

/* Rail (Column 1) */
.os-rail h2 { font-size: 11px; font-weight: 600; color: var(--os-muted); margin: 0 0 8px; text-transform: uppercase; letter-spacing: .06em; }
.os-rail-actions { display: flex; flex-direction: column; gap: 6px; }
.os-rail-actions > .os-button { width: 100%; justify-content: flex-start; }
.os-navigation { display: flex; flex-direction: column; gap: 4px; padding-top: 10px; margin-top: 10px; border-top: 1px solid var(--os-border); }
.os-nav-link { display: flex; align-items: center; gap: 8px; min-height: 28px; font-size: 12px; color: var(--os-muted); cursor: pointer; text-decoration: none; padding: 4px 6px; border-radius: 6px; transition: background .1s, color .1s; white-space: nowrap; }
.os-nav-link:hover { color: var(--os-text); background: var(--os-surface-hover); }

/* Center (Column 2) */
.os-section-head { margin-bottom: 12px; }
.os-section-toolbar { display: flex; align-items: center; justify-content: space-between; gap: 8px; min-height: 32px; flex-wrap: wrap; }
.os-tabs { display: flex; gap: 4px; align-items: center; flex-wrap: wrap; }
.os-tab { border: 0; border-radius: 6px; background: transparent; padding: 5px 10px; color: var(--os-muted); font-size: 12px; font-weight: 500; cursor: pointer; transition: background .1s, color .1s; white-space: nowrap; }
.os-tab:hover { color: var(--os-text); background: var(--os-surface-hover); }
.os-tab.active { background: var(--os-surface); color: var(--os-text); font-weight: 600; border: 1px solid var(--os-border); }

.os-filter-search { display: flex; align-items: center; gap: 10px; }
.os-search-input { background: rgba(0, 0, 0, 0.25); border: 1px solid var(--os-border); border-radius: 6px; padding: 4px 10px; font-size: 12px; color: var(--os-text); width: 140px; transition: border-color .15s; outline: none; }
.os-search-input:focus { width: 190px; border-color: var(--os-accent); }
.os-view-all { font-size: 12px; color: var(--os-muted); cursor: pointer; white-space: nowrap; }
.os-view-all:hover { color: var(--os-accent); }

/* Filter Pills */
.os-filter-pills { display: flex; gap: 6px; margin-bottom: 12px; flex-wrap: wrap; }
.os-filter-pill { border: 1px solid var(--os-border); border-radius: 20px; background: var(--os-surface); color: var(--os-muted); font-size: 12px; font-weight: 500; padding: 3px 10px; cursor: pointer; transition: background .1s, color .1s, border-color .1s; }
.os-filter-pill:hover { color: var(--os-text); background: var(--os-surface-hover); }
.os-filter-pill.active { background: var(--os-surface-hover); color: var(--os-accent); border-color: var(--os-accent); font-weight: 600; }

.os-cards { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 12px; }
.os-empty-placeholder { opacity: 0.6; padding: 28px 16px; grid-column: 1 / -1; text-align: center; font-size: 13px; color: var(--os-muted); }

.os-project-card { display: flex; flex-direction: column; gap: 6px; padding: 12px 14px; border: 1px solid var(--os-border); border-radius: 8px; background: var(--os-surface); transition: transform .1s, border-color .15s; }
.os-project-card:hover { border-color: var(--os-accent); transform: translateY(-1px); }
.os-card-top { display: flex; align-items: center; justify-content: space-between; gap: 6px; }
.os-badge { font-size: 11px; padding: 2px 7px; border-radius: 4px; font-weight: 600; text-transform: uppercase; letter-spacing: .02em; cursor: pointer; transition: opacity .15s; }
.os-badge:hover { opacity: .8; }
button.os-badge { border: 0; font-family: inherit; line-height: inherit; }
.os-badge.status-in_progress { background: rgba(34, 197, 94, 0.15); color: #4ade80; }
.os-badge.status-backlog { background: rgba(148, 163, 184, 0.15); color: #94a3b8; }
.os-badge.status-completed { background: rgba(56, 189, 248, 0.15); color: #38bdf8; }
.os-badge.status-paid { background: rgba(34, 197, 94, 0.15); color: #4ade80; }
.os-badge.status-unpaid { background: rgba(249, 115, 22, 0.15); color: #fb923c; }
.os-badge.badge-care-plan { background: rgba(168, 85, 247, 0.15); color: #c084fc; }
.os-badge.priority-high { background: rgba(249, 115, 22, 0.15); color: #fb923c; }
.os-badge.priority-medium { background: rgba(148, 163, 184, 0.15); color: #cbd5e1; }
.os-card-title, .os-card-open, .os-card-client-link { appearance: none; border: 0; border-radius: 0; background: transparent; padding: 0; font: inherit; text-align: left; max-width: 100%; overflow-wrap: anywhere; }
.os-card-title { font-size: 13px; font-weight: 600; line-height: 1.35; color: var(--os-text); cursor: pointer; word-break: break-word; }
.os-card-title:hover { color: var(--os-accent); text-decoration: underline; }
.os-card-client { font-size: 12px; color: var(--os-muted); }
.os-card-client-link { cursor: pointer; text-decoration: underline; text-underline-offset: 3px; }
.os-card-client-link:hover { color: var(--os-accent); }
.os-project-financials { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin: 4px 0; font-size: 11px; }
.os-project-fee-type { font-size: 10px; font-weight: 600; text-transform: uppercase; padding: 1px 5px; border-radius: 3px; background: var(--os-surface-hover); color: var(--os-muted); border: 1px solid var(--os-border); }
.os-project-budget-label { color: var(--os-muted); font-size: 11px; }
.os-project-budget-label strong { color: var(--os-text); }
.os-lead-pipeline-banner { display: flex; align-items: center; justify-content: space-between; padding: 6px 12px; margin-bottom: 12px; border-radius: 6px; background: var(--os-surface-hover); border: 1px solid var(--os-border); font-size: 12px; color: var(--os-muted); }
.os-lead-pipeline-banner strong { color: var(--os-accent); }
.os-client-projects { cursor: pointer; font: inherit; }
.os-client-projects:hover { color: var(--os-accent); border-color: var(--os-accent); }
.os-client-project-filter { display: flex; gap: 12px; justify-content: space-between; align-items: baseline; flex-wrap: wrap; margin-bottom: 12px; font-size: 12px; color: var(--os-muted); overflow-wrap: anywhere; }
.os-client-project-filter strong { color: var(--os-text); }
.os-app button:focus-visible, .os-modal-backdrop :is(button, input, select, textarea):focus-visible { outline: 2px solid var(--os-accent); outline-offset: 3px; }
.os-badge.status-archived, .os-badge.status-cancelled { background: var(--os-surface-hover); color: var(--os-muted); }
.os-client-meta { display: flex; gap: 8px; align-items: center; margin-top: 2px; }
.os-meta-tag { font-size: 12px; color: var(--os-muted); background: var(--os-surface-hover); padding: 2px 6px; border-radius: 4px; border: 1px solid var(--os-border); }
.os-card-bottom { display: flex; align-items: center; justify-content: space-between; gap: 6px; margin-top: auto; padding-top: 6px; border-top: 1px solid rgba(255, 255, 255, 0.05); font-size: 12px; color: var(--os-muted); }
.os-card-actions { display: inline-flex; align-items: center; gap: 6px; }
.os-card-action-btn { appearance: none; font-family: inherit; font-size: 11px; font-weight: 600; padding: 2px 7px; border-radius: 4px; background: var(--os-surface-hover); border: 1px solid var(--os-border); color: var(--os-text); cursor: pointer; transition: all .12s ease; line-height: 1.3; }
.os-card-action-btn:hover { background: color-mix(in srgb, var(--os-accent) 15%, var(--os-surface-hover)); border-color: var(--os-accent); color: var(--os-accent); }
.os-card-open { color: var(--os-accent); cursor: pointer; text-decoration: none; font-weight: 500; }
.os-card-open:hover { text-decoration: underline; }

/* Deliverables & Sub-pages Hierarchy */
.os-card-deliverables-summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 6px;
  margin-bottom: 2px;
  padding: 4px 8px;
  background: rgba(0, 0, 0, 0.25);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 5px;
  font-size: 11px;
}
.os-deliverables-count {
  color: var(--os-muted);
  font-weight: 500;
  display: flex;
  align-items: center;
  gap: 4px;
}
.os-toggle-deliverables {
  background: transparent;
  border: none;
  color: var(--os-accent);
  font-size: 11px;
  font-weight: 600;
  cursor: pointer;
  padding: 2px 5px;
  border-radius: 4px;
  transition: background .1s;
}
.os-toggle-deliverables:hover {
  background: var(--os-surface-hover);
  text-decoration: underline;
}
.os-deliverables-list {
  display: flex;
  flex-direction: column;
  gap: 3px;
  margin-top: 4px;
  margin-bottom: 4px;
  padding: 4px 0 4px 8px;
  border-left: 1px solid var(--os-border);
  background: rgba(0, 0, 0, 0.15);
  border-radius: 0 6px 6px 0;
  max-height: 220px;
  overflow-y: auto;
}
.os-deliverable-item {
  border: 0;
  background: transparent;
  text-align: left;
  font-family: inherit;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 3px 6px;
  border-radius: 4px;
  font-size: 11px;
  color: var(--os-muted);
  cursor: pointer;
  transition: background .1s, color .1s;
}
.os-deliverable-item:hover {
  background: var(--os-surface-hover);
  color: var(--os-text);
}
.os-deliverable-arrow {
  color: var(--os-accent);
  font-size: 11px;
  font-weight: bold;
}
.os-deliverable-name {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.os-deliverable-open {
  color: var(--os-accent);
  font-size: 10px;
  opacity: 0.4;
  transition: opacity .1s;
}
.os-deliverable-item:hover .os-deliverable-open {
  opacity: 1;
}

/* Agenda (Column 3) */
.os-agenda { background: var(--os-surface); border: 1px solid var(--os-border); border-radius: 8px; padding: 14px 16px; min-width: 0; }
.os-agenda-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px; }
.os-agenda-header h2 { font-size: 14px; font-weight: 700; color: var(--os-text); }
.os-agenda-tabs { display: flex; gap: 4px; margin-bottom: 12px; border-bottom: 1px solid var(--os-border); padding-bottom: 6px; flex-wrap: wrap; }
.os-agenda-tab { font-size: 12px; color: var(--os-muted); cursor: pointer; padding: 2px 6px; border-radius: 4px; transition: background .1s, color .1s; }
.os-agenda-tab:hover { color: var(--os-text); }
.os-agenda-tab.active { color: var(--os-text); font-weight: 600; background: var(--os-surface-hover); }
.os-agenda-note { font-size: 12px; color: color-mix(in srgb, var(--os-muted) 75%, var(--os-text)); margin: 0 0 8px; line-height: 1.4; }
.os-agenda-more { margin-top: 8px; width: 100%; }
.os-empty-state { display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 24px 12px; text-align: center; color: var(--os-muted); }
.os-empty-icon { font-size: 24px; color: #4ade80; margin-bottom: 4px; }
.os-empty-title { font-size: 12px; font-weight: 600; color: var(--os-text); margin-bottom: 2px; }
.os-empty-desc { font-size: 12px; line-height: 1.4; }
.os-agenda-footer { display: flex; justify-content: space-between; margin-top: 14px; padding-top: 10px; border-top: 1px solid var(--os-border); font-size: 11px; color: var(--os-muted); }
.os-agenda-footer a { color: var(--os-muted); text-decoration: none; cursor: pointer; }
.os-agenda-footer a:hover { color: var(--os-accent); }

.os-task-item { display: flex; align-items: center; gap: 8px; padding: 6px 10px; border-radius: 6px; background: var(--os-surface-hover); margin-bottom: 5px; cursor: pointer; transition: background .1s, border-color .1s; }
.os-task-item:hover { border-color: var(--os-accent); }
.os-task-item.os-task-waiting { border-left: 2px solid var(--os-warning, #d29922); }
.os-task-state { font-size: 11px; color: var(--os-warning, #d29922); flex-shrink: 0; }
.os-task-checkbox { width: 14px; height: 14px; border-radius: 3px; border: 1px solid var(--os-muted); flex-shrink: 0; cursor: pointer; }
.os-task-label { font-size: 12px; flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.os-task-date { font-size: 11px; color: #38bdf8; flex-shrink: 0; }
.os-task-project { font-size: 11px; color: var(--os-muted); max-width: 100px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; flex-shrink: 0; }
.os-suggest-project { border: 1px solid var(--os-border); border-radius: 4px; background: transparent; color: var(--os-accent); font: inherit; font-size: 11px; padding: 2px 6px; cursor: pointer; flex-shrink: 0; }
.os-suggest-project:hover { border-color: var(--os-accent); }
.os-project-suggestions { margin: 2px 0 8px; padding: 10px 12px; border: 1px solid var(--os-border); border-radius: 6px; background: var(--os-surface); display: grid; gap: 8px; }
.os-project-suggestions-head { display: grid; gap: 2px; }
.os-project-suggestion-list { display: grid; gap: 6px; }
.os-project-suggestion { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
.os-project-suggestion-copy { display: grid; gap: 1px; flex: 1 1 150px; min-width: 0; }
.os-project-suggestion-name { overflow-wrap: anywhere; font-weight: 550; }
.os-dismiss-project-suggestions { justify-self: start; }

/* ============================================================
   RESPONSIVE LAYOUT FOR MULTI-PANEL USAGE
   Adapts via Container Queries (panel width) with Viewport fallbacks
   ============================================================ */

/* Medium panel (~720px to 1120px) — When a side panel is opened */
@container osApp (max-width: 1120px) {
  .os-app {
    padding: 16px 18px;
    --os-gap: 14px;
  }
  .os-grid {
    grid-template-columns: 150px minmax(0, 1fr);
  }
  .os-rail {
    grid-column: 1;
    grid-row: 1 / 3;
  }
  .os-main {
    grid-column: 2;
    grid-row: 1;
  }
  .os-agenda {
    grid-column: 2;
    grid-row: 2;
    margin-top: 6px;
  }
  .os-pulse {
    grid-template-columns: repeat(2, 1fr);
    gap: 10px;
    padding-block: 10px;
    margin-bottom: 16px;
  }
  .os-metric:nth-child(3) {
    border-left: 0;
  }
}

/* Narrow panel (< 720px) — 3-panel split or narrow window */
@container osApp (max-width: 720px) {
  .os-shell {
    padding: 14px;
    --os-gap: 12px;
  }
  .os-header {
    flex-direction: column;
    align-items: stretch;
    gap: 10px;
    margin-bottom: 14px;
  }
  .os-header-actions {
    display: flex;
    justify-content: flex-end;
  }
  .os-capture {
    max-width: 100%;
    flex: 1 1 auto;
  }
  .os-grid {
    grid-template-columns: 1fr;
  }
  .os-rail {
    grid-column: 1;
    grid-row: auto;
    padding-bottom: 10px;
    border-bottom: 1px solid var(--os-border);
  }
  .os-rail-actions {
    flex-direction: row;
    flex-wrap: wrap;
    gap: 6px;
  }
  .os-rail-actions > .os-button {
    width: auto;
    flex: 1 1 110px;
    justify-content: center;
  }
  .os-navigation {
    flex-direction: row;
    flex-wrap: wrap;
    gap: 6px;
    border-top: none;
    padding-top: 0;
    margin-top: 6px;
  }
  .os-nav-link {
    background: var(--os-surface);
    border: 1px solid var(--os-border);
    padding: 4px 8px;
    font-size: 11px;
  }
  .os-main {
    grid-column: 1;
    grid-row: auto;
  }
  .os-agenda {
    grid-column: 1;
    grid-row: auto;
    margin-top: 0;
  }
  .os-cards {
    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    gap: 8px;
  }
  .os-pulse {
    grid-template-columns: repeat(2, 1fr);
    padding-block: 8px;
    margin-bottom: 14px;
    gap: 6px;
  }
  .os-metric {
    padding: 4px 8px;
  }
  .os-metric-value {
    font-size: 18px;
  }
}

/* Extra Narrow Panel (< 480px) */
@container osApp (max-width: 480px) {
  .os-shell {
    padding: 10px;
  }
  .os-pulse {
    grid-template-columns: 1fr;
    gap: 4px;
  }
  .os-metric {
    border-left: none !important;
    padding-left: 0;
    border-bottom: 1px solid rgba(255, 255, 255, 0.05);
    padding-bottom: 4px;
  }
  .os-cards {
    grid-template-columns: 1fr;
  }
  .os-rail-actions > .os-button {
    flex: 1 1 110px;
  }
  .os-identity { flex-shrink: 1; }
  .os-search-input, .os-search-input:focus { width: 100%; max-width: 170px; }
  .os-cashflow { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .os-collection-rate { grid-column: 1 / -1; }
  .os-cash-action:last-child { grid-column: 1 / -1; }
  .os-pulse { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

/* Interactive Modals */
.os-modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.65);
  backdrop-filter: blur(4px);
  z-index: 10000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  color: var(--os-text);
  font: 14px/1.4 -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}
